begin;
create function pg_temp.assert(ok boolean,message text) returns void language plpgsql as $$begin if ok is not true then raise exception 'FAIL: %',message;end if;end $$;
insert into auth.users(id,email,is_anonymous) values('fd870000-0000-4000-8000-000000000001','shared-payroll@example.invalid',false);
set local role authenticated;
select set_config('request.jwt.claim.sub','fd870000-0000-4000-8000-000000000001',true);
select public.setup_business('Disposable shared payroll dimensions','Payroll owner');
reset role;
do $$declare t uuid:=app_private.current_tenant_id();e uuid;w uuid;p uuid;b uuid;d date:=(now() at time zone 'Asia/Dhaka')::date;month date:=date_trunc('month',now() at time zone 'Asia/Dhaka')::date;future date:=(date_trunc('month',now() at time zone 'Asia/Dhaka')+interval '2 months')::date;body jsonb;begin
 select wallet_id into w from public.get_payment_wallets() where type='cash';
 e:=(public.save_employee(jsonb_build_object('name','Shared payroll operator','phones',jsonb_build_array(jsonb_build_object('phone','01700000871','is_primary',true)),'business_unit','gas_business','business_allocations','{"lpg":60,"stove":40}'::jsonb,'terms',jsonb_build_object('monthly_salary',10000,'effective_from',month,'is_active',true)),gen_random_uuid())->>'employee_id')::uuid;
 perform public.get_finance_analysis(jsonb_build_object('business_id',t,'from',month,'to',d));
 perform pg_temp.assert((select sum(amount)=6000 from public.accounting_lines where tenant_id=t and account='employee_expense' and business_category='lpg'),'Salary accrual retains 60% LPG ownership');
 body:=jsonb_build_object('action','pay','items',jsonb_build_array(jsonb_build_object('employee_id',e,'kind','salary','period',future,'payment_date',d,'payments',jsonb_build_array(jsonb_build_object('wallet_id',w,'amount',5000)))));
 p:=(public.employee_payment_operation(body,gen_random_uuid())->'payment_ids'->>0)::uuid;
 perform public.save_employee((public.get_employee_profile(e)->'employee')||'{"business_allocations":{"logistics":100}}'::jsonb,gen_random_uuid());
 perform public.employee_payment_operation(jsonb_set(body,'{items,0,payments,0,amount}','1000'),gen_random_uuid());
 perform pg_temp.assert((select sum((business_amounts->>'lpg')::numeric)=-3600 and sum((business_amounts->>'stove')::numeric)=-2400 from public.wallet_transactions where tenant_id=t),'Future salary advance keeps original 60/40 after reassignment');
 perform public.employee_payment_operation(jsonb_build_object('action','reverse_payment','payment_id',p,'payment_date',d,'reason','Actual advance funds returned'),gen_random_uuid());
 perform pg_temp.assert((select sum((business_amounts->>'lpg')::numeric)=-600 and sum((business_amounts->>'stove')::numeric)=-400 from public.wallet_transactions where tenant_id=t),'Advance return restores original 60/40');
 b:=(public.employee_payment_operation(jsonb_build_object('action','pay','items',jsonb_build_array(jsonb_build_object('employee_id',e,'kind','bonus','bonus_name','Logistics bonus','payment_date',d,'payments',jsonb_build_array(jsonb_build_object('wallet_id',w,'amount',700))))),gen_random_uuid())->'payment_ids'->>0)::uuid;
 perform public.save_employee((public.get_employee_profile(e)->'employee')||'{"business_allocations":{"lpg":100}}'::jsonb,gen_random_uuid());
 perform public.employee_payment_operation(jsonb_build_object('action','reverse_payment','payment_id',b,'payment_date',d,'reason','Original bonus money returned'),gen_random_uuid());
 perform public.get_finance_analysis(jsonb_build_object('business_id',t,'from',month,'to',d));
 perform pg_temp.assert((select sum(amount)=6000 from public.accounting_lines where tenant_id=t and account='employee_expense' and business_category='lpg'),'Established salary accrual does not move with later assignment');
 perform pg_temp.assert((select sum(amount)=0 from public.accounting_lines where tenant_id=t and account='employee_expense' and business_category='logistics'),'Bonus and return both retain Logistics ownership');
 perform pg_temp.assert(not exists(select 1 from public.accounting_lines where tenant_id=t group by journal_id,business_category having sum(amount)<>0),'All payroll business equations balance');
 perform pg_temp.assert((public.get_wallet_ledger()->>'total')::integer=5,'Ledger resolves every actual payroll source');
 perform pg_temp.assert((public.get_wallet_ledger('{"search":"","wallet":"","type":"","business":"","from":"","to":"","min":"","max":"","direction":"all","sort":"date_desc"}')->>'total')::integer=5,'Exact browser blank filters load payroll ledger');
end $$;
set constraints all immediate;
select 'PASS: shared salary accrual, future advances, reassignment, original-month ownership, bonus and returned-fund allocations';
rollback;
